\section{Introduction}

\subsection{The objective}

Fix a finite set $\Omega$ of \emph{responses}, a strictly positive \emph{reference policy}
$p : \Omega \to (0,\infty)$ with $\sum_y p(y) = 1$, a \emph{reward} $r : \Omega \to \R$,
and a \emph{regularization strength} (or \emph{temperature}) $\beta > 0$. For a probability
distribution $q$ on $\Omega$ define the \emph{objective}
\[
  J_\beta(q) \;=\; \sum_{y \in \Omega} q(y) r(y) \;-\; \beta \sum_{y \in \Omega} q(y)\log\frac{q(y)}{p(y)}
  \;=\; \E_q[r] - \beta\,\KL(q\|p).
\]
This is the alignment objective used to tune a generative model against a learned or
symbolic reward: maximize reward while paying an information price for departing from the
reference behaviour. A third term, a \emph{pretraining mix-in}
$\gamma\,\E_{x\sim d}[\log q(x)]$ with coefficient $\gamma\ge 0$ and pretraining
distribution $d$, is often added to prevent regression on general capabilities; we write
$J^{\ptx}_{\beta,\gamma}$ for the augmented objective.

Define the \emph{partition function}, \emph{optimal (Gibbs) policy} and \emph{free energy}
\[
  Z_\beta(r,p) = \sum_y p(y)e^{r(y)/\beta}, \qquad
  \pi_\beta(y) = \frac{p(y)e^{r(y)/\beta}}{Z_\beta(r,p)}, \qquad
  F_\beta(r,p) = \beta\log Z_\beta(r,p).
\]
The classical variational (Donsker--Varadhan / Gibbs) fact is that $\pi_\beta$ is the
unique maximizer of $J_\beta$, with $\max_q J_\beta(q) = F_\beta(r,p)$; equivalently
\begin{equation}\label{eq:var}
  J_\beta(q) \;=\; F_\beta(r,p) \;-\; \beta\,\KL(q\|\pi_\beta) \qquad \text{for every } q.
\end{equation}
We take \eqref{eq:var} as given and ask a different question.

\subsection{The question}

Alignment theory is usually pursued analytically. But in practice the response space is not
amorphous: a symbolic verifier reports a \emph{set} of satisfied constraints, a sequence
model emits a \emph{tuple} of tokens, a retrieval pipeline returns a \emph{subset} of facts.
On such combinatorial objects the objective above admits not merely bounds but \emph{exact
closed forms}. We carry out that program in two settings.

\smallskip
\noindent\textbf{(A) Product structure} (Section~\ref{sec:tensor}). $\Omega = \Omega_1\times\Omega_2$
with $p = p_1\otimes p_2$ and $r(y_1,y_2) = r_1(y_1)+r_2(y_2)$: everything factorizes or
adds, and iterating gives exact linear scaling laws.

\smallskip
\noindent\textbf{(B) Boolean-lattice structure} (Sections~\ref{sec:lattice}--\ref{sec:fkg}).
$\Omega = 2^{[n]}$ with $p$ uniform: the natural model of a symbolic reward, where the
response $S$ is the set of the $n$ checkable features it satisfies.

\section{Notation and preliminaries}

Throughout $\Omega$ is a finite nonempty set. A function $q : \Omega\to\R$ is a
\emph{distribution} if $\sum_y q(y) = 1$, and a \emph{positive distribution} if in addition
$q > 0$ pointwise. For positive distributions $q,g$ set
\[
  \KL(q\|g) = \sum_y q(y)\log\frac{q(y)}{g(y)}, \qquad \Ent(q) = -\sum_y q(y)\log q(y).
\]
Write $\sigma(t) = e^t/(1+e^t)$ for the \emph{logistic} function and
$H(\theta) = -\theta\log\theta - (1-\theta)\log(1-\theta)$ for the \emph{binary entropy}.

\begin{lemma}[Logistic basics]\label{lem:logistic}
For all $t\in\R$: $0 < \sigma(t) < 1$; $1-\sigma(t) = (1+e^t)^{-1}$; $\sigma$ is strictly
increasing; $\sigma(t)\ge \tfrac12$ whenever $t \ge 0$; and $1-\sigma(t) \le e^{-t}$.
\end{lemma}

\begin{proof}
Positivity and the complement formula are immediate from $\sigma(t) = e^t/(1+e^t)$ and
$1+e^t>0$; the complement formula gives $\sigma(t)<1$. Strict monotonicity follows from
$\sigma(s)<\sigma(t) \iff e^s(1+e^t) < e^t(1+e^s) \iff e^s<e^t$. For $t\ge 0$ we have
$e^t\ge 1$, so $2e^t \ge 1+e^t$ and $\sigma(t)\ge\tfrac12$. Finally $e^t \le 1+e^t$ gives
$1-\sigma(t) = (1+e^t)^{-1}\le e^{-t}$.
\end{proof}

For the Boolean lattice we identify $\Omega = 2^{[n]}$ with the subsets of
$[n]=\{1,\dots,n\}$, ordered by inclusion with meet $\cap$ and join $\cup$. The
\emph{uniform reference policy} is $p(S) = 2^{-n}$, a positive distribution since there are
$2^n$ subsets.

\section{Tensorization: exact scaling laws on product spaces}\label{sec:tensor}

Let $\Omega_1,\Omega_2$ be finite and nonempty. Given $p_i : \Omega_i\to\R$, the
\emph{product reference} is $(p_1\otimes p_2)(y_1,y_2) = p_1(y_1)p_2(y_2)$; given
$r_i : \Omega_i\to\R$, the \emph{additive reward} is
$(r_1\oplus r_2)(y_1,y_2) = r_1(y_1)+r_2(y_2)$.

\begin{theorem}[Multiplicativity of the partition function]\label{thm:Zprod}
$Z_\beta(r_1\oplus r_2,\ p_1\otimes p_2) = Z_\beta(r_1,p_1)\, Z_\beta(r_2,p_2)$.
\end{theorem}

\begin{proof}[Proof sketch]
Expand the double sum, use $e^{(u+v)/\beta} = e^{u/\beta}e^{v/\beta}$, and apply the
distributive law $\bigl(\sum_a f(a)\bigr)\bigl(\sum_b g(b)\bigr) = \sum_{a,b}f(a)g(b)$ in
reverse.
\end{proof}

\begin{theorem}[The aligned policy of a separable problem is a product]\label{thm:piprod}
If $p_1,p_2$ are positive distributions then
$\pi_\beta(r_1\oplus r_2,\ p_1\otimes p_2) = \pi_\beta(r_1,p_1)\otimes\pi_\beta(r_2,p_2)$.
\end{theorem}

\begin{proof}[Proof sketch]
Both sides at $(y_1,y_2)$ equal $p_1(y_1)e^{r_1(y_1)/\beta}p_2(y_2)e^{r_2(y_2)/\beta}$
divided by $Z_1Z_2$, by Theorem~\ref{thm:Zprod}.
\end{proof}

Theorem~\ref{thm:piprod} is the precise sense in which \emph{alignment cannot invent
correlations the reward did not ask for}.

\begin{theorem}[Additivity]\label{thm:addit}
For positive distributions $q_i,g_i$ on $\Omega_i$,
$\KL(q_1\otimes q_2\|g_1\otimes g_2) = \KL(q_1\|g_1)+\KL(q_2\|g_2)$, and consequently
\[
  J_\beta(q_1\otimes q_2) = J_\beta(q_1)+J_\beta(q_2), \qquad
  F_\beta(r_1\oplus r_2, p_1\otimes p_2) = F_\beta(r_1,p_1)+F_\beta(r_2,p_2).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Since $\frac{q_1(a)q_2(b)}{g_1(a)g_2(b)} = \frac{q_1(a)}{g_1(a)}\cdot\frac{q_2(b)}{g_2(b)}$
the logarithm splits; summing and using $\sum_a q_1(a)=\sum_b q_2(b)=1$ gives additivity of
$\KL$. The same normalization argument gives additivity of $\E[r_1\oplus r_2]$, hence of $J$.
Free-energy additivity is $\log(Z_1Z_2) = \log Z_1 + \log Z_2$.
\end{proof}

\subsection{Tensor powers and linear scaling laws}

Let $\alpha$ be finite and nonempty, $n\ge 0$, and consider length-$n$ responses
$y \in \alpha^{[n]}$ with i.i.d.\ reference $p^{\otimes n}(y) = \prod_i p(y_i)$ and additive
reward $r^{\oplus n}(y) = \sum_i r(y_i)$.

\begin{theorem}[Tensor-power law]\label{thm:tensorpower}
$Z_\beta(r^{\oplus n}, p^{\otimes n}) = Z_\beta(r,p)^n$ and
$\pi_\beta(r^{\oplus n},p^{\otimes n}) = \pi_\beta(r,p)^{\otimes n}$.
\end{theorem}

\begin{proof}[Proof sketch]
The distributive law in the form
$\prod_{i=1}^{n}\sum_{a\in\alpha} h_i(a) = \sum_{y\in\alpha^{[n]}}\prod_i h_i(y_i)$,
applied to $h_i(a) = p(a)e^{r(a)/\beta}$, identifies the $n$-fold partition sum with
$Z_1^{\,n}$; the policy statement follows by dividing.
\end{proof}

\begin{corollary}[Linear scaling laws]\label{cor:scaling}
With $p$ a positive distribution and $\beta > 0$,
\[
  F_\beta(r^{\oplus n},p^{\otimes n}) = n F_\beta(r,p), \quad
  \E_{\pi^{(n)}}[r^{\oplus n}] = n \E_\pi[r], \quad
  \KL(\pi^{(n)}\|p^{\otimes n}) = n \KL(\pi\|p).
\]
Moreover, with i.i.d.\ pretraining distribution $d^{\otimes n}$,
$J^{\ptx}_{\beta,\gamma}(\pi^{(n)}) = n\,J^{\ptx}_{\beta,\gamma}(\pi)$.
\end{corollary}

\begin{proof}[Proof sketch]
Free energy: $\log(Z_1^n) = n\log Z_1$. Reward: a marginalization identity --- again the
distributive law --- shows that integrating a one-coordinate observable against a product
measure returns the one-coordinate expectation, and there are $n$ coordinates. Drift: read
$\KL$ off $\beta\KL(\pi\|p) = \E_\pi[r] - F_\beta$ and divide by $\beta>0$. For the mix-in,
$\Ent(d^{\otimes n}) = n\Ent(d)$ and $\KL(d^{\otimes n}\|\pi^{(n)}) = n\KL(d\|\pi)$ by the
same argument, and the augmented value at the aligned policy is an affine combination of
these.
\end{proof}

\begin{remark}
Reward gain, information drift and pretraining cost all carry the exponent $n^1$; no choice
of $(\beta,\gamma)$ can asymptotically rebalance them. Only per-coordinate budgets are
stable under changing response length.
\end{remark}

\section{The Boolean lattice: transfer principle and exact solution}\label{sec:lattice}

\begin{theorem}[Transfer principle]\label{thm:transfer}
For every $n\ge0$ and every $f:\N\to\R$,
\[
  \sum_{S\subseteq[n]} f(|S|) \;=\; \sum_{k=0}^{n}\binom nk f(k).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition the power set into level sets $\mathcal P_k = \{S : |S| = k\}$. On $\mathcal P_k$
the summand is the constant $f(k)$ and $|\mathcal P_k| = \binom nk$.
\end{proof}

\begin{corollary}[Generating function of the cube]\label{cor:genfun}
For all $x\in\R$, $\ \sum_{S\subseteq[n]} x^{|S|} = (1+x)^n$.
\end{corollary}

\begin{definition}\label{def:count}
On $\Omega = 2^{[n]}$ with uniform reference, the \emph{counting reward} with per-feature
value $a\in\R$ is $r(S) = a|S|$, and the \emph{Bernoulli feature policy} with parameter
$\theta$ is $\Ber_n^\theta(S) = \theta^{|S|}(1-\theta)^{\,n-|S|}$.
\end{definition}

\begin{theorem}[The partition function is a binomial evaluation]\label{thm:Zcount}
$\displaystyle Z_\beta(a|\cdot|,\unif) = \left(\frac{1+e^{a/\beta}}{2}\right)^{\! n}$.
\end{theorem}

\begin{proof}[Proof sketch]
Each term is $2^{-n}e^{a|S|/\beta} = 2^{-n}(e^{a/\beta})^{|S|}$. Factor out $2^{-n}$ and
apply Corollary~\ref{cor:genfun} with $x = e^{a/\beta}$.
\end{proof}

\begin{theorem}[Alignment on the Boolean lattice equals i.i.d.\ Bernoulli features]\label{thm:bernoulli}
For all $n,a,\beta$,
\[
  \pi_\beta(a|\cdot|,\unif) \;=\; \Ber_n^{\theta}, \qquad
  \theta \;=\; \sigma\!\left(\frac a\beta\right) \;=\; \frac{e^{a/\beta}}{1+e^{a/\beta}}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write $E = e^{a/\beta}$. The Gibbs numerator at $S$ is $2^{-n}E^{|S|}$ and the denominator
is $((1+E)/2)^n$ by Theorem~\ref{thm:Zcount}, so $\pi(S) = E^{|S|}/(1+E)^n$. Conversely
$\theta = E/(1+E)$ and $1-\theta = 1/(1+E)$ by Lemma~\ref{lem:logistic}, whence
$\Ber_n^\theta(S) = E^{|S|}/(1+E)^{|S|}\cdot(1+E)^{-(n-|S|)} = E^{|S|}/(1+E)^n$, using
$|S|\le n$ to split $(1+E)^{|S|}(1+E)^{n-|S|} = (1+E)^n$.
\end{proof}

\begin{remark}
The logistic link is \emph{derived}, not assumed; and $a,\beta$ enter only through the ratio
$a/\beta$, so the counting-reward alignment problem has a one-dimensional effective
parameter. Theorem~\ref{thm:bernoulli} also exhibits the Boolean-lattice problem as an
instance of Section~\ref{sec:tensor} with $\alpha=\{0,1\}$.
\end{remark}

\section{The induced law of the reward statistic}

\begin{theorem}[Binomial law of the aligned policy]\label{thm:binlaw}
For $0\le k\le n$ and $\theta = \sigma(a/\beta)$,
\[
  \pi_\beta\bigl(\{S : |S| = k\}\bigr) = \binom nk \theta^k(1-\theta)^{\,n-k}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The level set has $\binom nk$ elements, and by Theorem~\ref{thm:bernoulli} the aligned
policy is constant on it, equal to $\theta^k(1-\theta)^{n-k}$.
\end{proof}

We write $m_k(\theta) = \binom nk\theta^k(1-\theta)^{n-k}$ for the \emph{level masses}.

\begin{lemma}[Combinatorial mean identity]\label{lem:mean}
For all $n\ge 0$ and $x,y\in\R$,
$\ \sum_{k=0}^{n} k\binom nk x^k y^{\,n-k} = n\,x\,(x+y)^{\,n-1}$.
\end{lemma}

\begin{proof}[Proof sketch]
For $n=0$ both sides vanish. For $n = m+1$, drop the $k=0$ term and reindex $k\mapsto k+1$.
Pascal's absorption identity $(m+1)\binom mk = \binom{m+1}{k+1}(k+1)$ converts each summand
into $(m+1)x\binom mk x^k y^{\,m-k}$, and $\sum_k\binom mk x^ky^{m-k} = (x+y)^m$.
\end{proof}

\begin{theorem}[Exact mean and expected reward]\label{thm:mean}
$\E_{\Ber_n^\theta}[|S|] = n\theta$ for any $\theta$; consequently under the aligned policy
for the counting reward, $\E_{\pi_\beta}[a|S|] = a\,n\,\sigma(a/\beta)$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:transfer} the expectation is $\sum_k k\binom nk\theta^k(1-\theta)^{n-k}$,
which by Lemma~\ref{lem:mean} with $x=\theta$, $y=1-\theta$ equals $n\theta$.
\end{proof}

\section{Free energy, entropy, drift, order and collapse}

\begin{theorem}[Free energy]\label{thm:freeenergy}
$\displaystyle F_\beta(a|\cdot|,\unif) = n\beta\log\frac{1+e^{a/\beta}}{2}$.
\end{theorem}

\begin{theorem}[Exact information drift]\label{thm:drift}
For $\beta>0$,
\[
  \KL\bigl(\pi_\beta \,\big\|\, \unif\bigr) \;=\; n\left(\frac a\beta\,\sigma\!\left(\frac a\beta\right) - \log\frac{1+e^{a/\beta}}{2}\right).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Evaluate \eqref{eq:var} at $q=\pi_\beta$: $\E_{\pi_\beta}[r] - \beta\KL(\pi_\beta\|p) = F_\beta$.
Substitute Theorem~\ref{thm:mean} and Theorem~\ref{thm:freeenergy}, then cancel $\beta>0$.
\end{proof}

\begin{theorem}[Entropy, entropy form of the drift, and consistency]\label{thm:entropy}
For $0<\theta<1$, $\Ent(\Ber_n^\theta) = n H(\theta)$. For any positive distribution $q$ on
$2^{[n]}$, $\KL(q\|\unif) = n\log 2 - \Ent(q)$. Combining these with
Theorem~\ref{thm:drift} yields, for every $t\in\R$,
\[
  t\,\sigma(t) - \log\frac{1+e^t}{2} \;=\; \log 2 - H\bigl(\sigma(t)\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$\log\Ber_n^\theta(S) = |S|\log\theta + (n-|S|)\log(1-\theta)$, so
$\Ent = -\log\theta\cdot\E[|S|] - \log(1-\theta)(n-\E[|S|])$; insert $\E[|S|]=n\theta$. With
$p(S)=2^{-n}$ constant, $\log\frac{q(S)}{p(S)} = n\log2 + \log q(S)$; sum against $q$. The
identity follows by computing the drift both ways at $n=1$, where $t = a/\beta$ ranges over
all of $\R$.
\end{proof}

\begin{remark}
At $t=0$ both sides vanish: $\sigma(0)=\tfrac12$ and $H(\tfrac12)=\log2$.
\end{remark}

\begin{theorem}[Alignment is order-preserving]\label{thm:monotone}
Let $\tfrac12\le\theta\le1$. Then $\Ber_n^\theta$ is a monotone measure on the Boolean
lattice: $S\subseteq T$ implies $\Ber_n^\theta(S)\le\Ber_n^\theta(T)$. In particular, for
$a\ge0$ and $\beta>0$ the aligned policy is monotone.
\end{theorem}

\begin{proof}[Proof sketch]
With $j=|T|-|S|\ge0$ and $n-|S| = (n-|T|)+j$,
\[
  \Ber_n^\theta(S) = \theta^{|S|}(1-\theta)^{n-|T|}(1-\theta)^j, \qquad
  \Ber_n^\theta(T) = \theta^{|S|}(1-\theta)^{n-|T|}\theta^j,
\]
and $0\le1-\theta\le\theta$ gives $(1-\theta)^j\le\theta^j$. For the last claim use
$\sigma(a/\beta)\ge\tfrac12$ from Lemma~\ref{lem:logistic}.
\end{proof}

\begin{theorem}[Log-concavity of the level masses]\label{thm:logconcave}
For $0\le\theta\le1$ and all $k\ge0$,
$\ m_k(\theta)m_{k+2}(\theta) \le m_{k+1}(\theta)^2$.
\end{theorem}

\begin{proof}[Proof sketch]
First, $\binom nk\binom n{k+2}\le\binom n{k+1}^2$: if $k\ge n$ the left side vanishes;
otherwise use $\binom{n}{k+1}(k+1)=\binom nk(n-k)$ and
$\binom{n}{k+2}(k+2)=\binom{n}{k+1}(n-k-1)$ together with
$(k+1)(n-k-1)\le(k+2)(n-k)$, multiplying through by $(n-k)(k+2)>0$. Second, the powers
match: $\theta^k\theta^{k+2} = (\theta^{k+1})^2$ and, when $k+2\le n$,
$(n-k)+(n-k-2) = 2(n-k-1)$. Multiply the coefficient inequality by the common non-negative
power factor; the case $k+2>n$ is handled by $m_{k+2}=0$.
\end{proof}

\begin{theorem}[Unimodality: descent persists]\label{thm:unimodal}
Let $0\le\theta\le1$ and suppose $m_{k+1}(\theta)>0$ and $m_{k+1}(\theta)\le m_k(\theta)$.
Then $m_{k+2}(\theta)\le m_{k+1}(\theta)$.
\end{theorem}

\begin{proof}
Multiply $m_{k+1}\le m_k$ by $m_{k+2}\ge0$ to get $m_{k+1}m_{k+2}\le m_km_{k+2}$, apply
Theorem~\ref{thm:logconcave} to get $m_{k+1}m_{k+2}\le m_{k+1}^2$, and cancel the positive
factor $m_{k+1}$.
\end{proof}

\begin{remark}
The distribution of ``how many checks the answer passed'' under the aligned policy has a
single mode: a model aligned to a linear symbolic reward cannot split into two separated
quality populations. Bimodal reward hacking is impossible in this regime.
\end{remark}

\begin{theorem}[Quantitative reward hacking]\label{thm:collapse}
Let $a\ge0$ and $\beta>0$. Then
\[
  \pi_\beta\bigl([n]\bigr) \;=\; \sigma\!\left(\frac a\beta\right)^{\!n} \;\ge\; 1 - n\,e^{-a/\beta}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:bernoulli} the mass on the top element is $\theta^n$ with
$\theta=\sigma(a/\beta)$. Bernoulli's inequality $(1+u)^n\ge1+nu$ with $u=\theta-1\ge-1$
gives $\theta^n\ge1-n(1-\theta)$, and $1-\theta\le e^{-a/\beta}$ by
Lemma~\ref{lem:logistic}.
\end{proof}

\begin{theorem}[Strict antitonicity in the regularization strength]\label{thm:antitone}
Let $n\ge1$, $a>0$, $0<\beta_1<\beta_2$. Then
\[
  a n\,\sigma\!\left(\frac{a}{\beta_2}\right) < a n\,\sigma\!\left(\frac{a}{\beta_1}\right),
  \qquad
  \pi_{\beta_2}\bigl([n]\bigr) < \pi_{\beta_1}\bigl([n]\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$a/\beta_2 < a/\beta_1$, so $\sigma(a/\beta_2)<\sigma(a/\beta_1)$ by strict monotonicity of
$\sigma$. Multiply by the positive constant $an$ for the first claim; raise to the $n$-th
power, using positivity of $\sigma$ and $n\ge1$, for the second.
\end{proof}

\begin{remark}[No free lunch]
Any tightening of the regularization that reduces collapse necessarily reduces reward, and
any loosening that increases reward necessarily increases collapse.
\end{remark}

\section{Beyond additivity: supermodular rewards, FKG and Holley}\label{sec:fkg}

\begin{definition}\label{def:supermod}
A reward $r : 2^{[n]}\to\R$ is \emph{supermodular} if
$r(S)+r(T)\le r(S\cap T)+r(S\cup T)$ for all $S,T$, and \emph{modular} if equality always
holds. The \emph{rule bonus} with premise set $R$ and value $c$ is
$\Bonus_{R,c}(S) = c\,\ind[R\subseteq S]$.
\end{definition}

\begin{proposition}[The reward class]\label{prop:cone}
\emph{(i)} $r(S)=a|S|$ is modular for every sign of $a$.
\emph{(ii)} $\Bonus_{R,c}$ is supermodular for every $R$ and every $c\ge0$.
\emph{(iii)} Supermodular rewards form a convex cone.
Consequently every reward $r(S) = a|S| + \sum_j c_j\ind[R_j\subseteq S]$ with $c_j\ge0$ is
supermodular.
\end{proposition}

\begin{proof}[Proof sketch]
(i) is $|S\cap T|+|S\cup T| = |S|+|T|$ scaled by $a$. (ii) is a four-case check: if
$R\subseteq S$ and $R\subseteq T$ both sides equal $2c$; if $R$ lies in exactly one, the
left side is $c$ and the right side is at least $c$ since $R\subseteq S\cup T$; if in
neither, the left side is $0$ and the right side is a sum of terms in $\{0,c\}$ with
$c\ge0$. (iii) is immediate from linearity of the defining inequality.
\end{proof}

\begin{theorem}[The aligned policy is log-supermodular]\label{thm:logsuper}
Let $\beta>0$ and let $r$ be supermodular. Then $\pi_\beta$ (uniform reference) satisfies
the FKG lattice condition
$\pi_\beta(S)\pi_\beta(T)\le\pi_\beta(S\cap T)\pi_\beta(S\cup T)$ for all $S,T$.
\end{theorem}

\begin{proof}[Proof sketch]
Each $\pi_\beta(S) = 2^{-n}e^{r(S)/\beta}/Z$ with the same positive constants on both sides,
so the claim reduces to
$e^{r(S)/\beta}e^{r(T)/\beta}\le e^{r(S\cap T)/\beta}e^{r(S\cup T)/\beta}$, i.e.\ to
Definition~\ref{def:supermod} divided by $\beta>0$.
\end{proof}

We invoke the Fortuin--Kasteleyn--Ginibre inequality (a corollary of the Ahlswede--Daykin
four-functions theorem) in the form: \emph{if $\mu\ge0$ on a finite distributive lattice
satisfies $\mu(x)\mu(y)\le\mu(x\wedge y)\mu(x\vee y)$, then for all non-negative increasing
$f,g$,}
\[
  \Bigl(\sum_x \mu(x)f(x)\Bigr)\Bigl(\sum_x \mu(x)g(x)\Bigr)
  \le \Bigl(\sum_x\mu(x)\Bigr)\Bigl(\sum_x\mu(x)f(x)g(x)\Bigr).
\]

\begin{theorem}[Positive association under alignment]\label{thm:fkg}
Let $\beta>0$, let $r$ be supermodular, and let $f,g:2^{[n]}\to\R$ be non-negative and
monotone increasing. Then $\E_{\pi_\beta}[f]\,\E_{\pi_\beta}[g] \le \E_{\pi_\beta}[fg]$.
\end{theorem}

\begin{corollary}[Feature entanglement]\label{cor:entangle}
For any two features $i,j\in[n]$, under the aligned policy of any supermodular reward,
$\Prob[i\in S]\,\Prob[j\in S] \le \Prob[i\in S \text{ and } j\in S]$.
\end{corollary}

\begin{lemma}\label{lem:monopolicy}
If $\beta>0$ and $r$ is monotone increasing, then $\pi_\beta$ is monotone on the lattice.
\end{lemma}

We use Holley's inequality: \emph{if $\mu,\nu\ge0$ on a finite distributive lattice have
equal total mass and satisfy $\mu(x)\nu(y)\le\mu(x\wedge y)\nu(x\vee y)$ for all $x,y$, then
$\sum_x\mu(x)h(x)\le\sum_x\nu(x)h(x)$ for every non-negative increasing $h$.}

\begin{theorem}[Alignment dominates the reference]\label{thm:holley}
Let $\beta>0$ and let $r$ be monotone increasing. Then for every non-negative monotone
increasing observable $h$, $\ \E_{\unif}[h] \le \E_{\pi_\beta}[h]$: the aligned policy
stochastically dominates the reference, uniformly in $\beta$.
\end{theorem}

\begin{proof}[Proof sketch]
Both are probability distributions, so total masses agree. The Holley condition reads
$\unif(S)\pi_\beta(T)\le\unif(S\cap T)\pi_\beta(S\cup T)$; the uniform factors are equal
(both $2^{-n}$) and $\pi_\beta(T)\le\pi_\beta(S\cup T)$ by Lemma~\ref{lem:monopolicy}.
\end{proof}

\section{Algorithms}

\begin{algorithmbox}[Exact aligned-policy profile]
\emph{Input:} $n$, $a$, $\beta>0$. \emph{Output:} $t = a/\beta$, $\theta=\sigma(t)$,
$Z = ((1+e^t)/2)^n$, $F = n\beta\log\frac{1+e^t}{2}$, expected reward $an\theta$, entropy
$nH(\theta)$, drift $n(t\theta - \log\frac{1+e^t}{2})$, top mass $\theta^n$ and the bound
$1-ne^{-t}$. \emph{Cost:} $O(1)$ arithmetic operations versus $\Theta(2^n)$ for naive
enumeration. Evaluate $\sigma$ and $\log\frac{1+e^t}{2} = \mathrm{softplus}(t)-\log2$ in
numerically stable form.
\end{algorithmbox}

\begin{algorithmbox}[Level-mass profile and mode]
\emph{Input:} $n$, $\theta$. \emph{Output:} $(m_0,\dots,m_n)$ and the mode.
\emph{Method:} the ratio recurrence $m_{k+1}/m_k = \frac{n-k}{k+1}\cdot\frac{\theta}{1-\theta}$
starting from $m_0=(1-\theta)^n$. \emph{Cost:} $O(n)$, with no binomial coefficients formed
explicitly. Correctness of the early-stopping mode search follows from
Theorem~\ref{thm:unimodal}.
\end{algorithmbox}

\begin{algorithmbox}[Brute-force lattice verifier]
\emph{Input:} $n\le20$, reward oracle $r$, $\beta$. \emph{Output:} the exact Gibbs policy
over all $2^n$ subsets and all derived quantities. \emph{Cost:} $\Theta(2^n)$. This is the
reference implementation against which the closed forms are checked, and the only available
route for general supermodular rewards.
\end{algorithmbox}

\begin{algorithmbox}[Supermodularity certification]
\emph{Input:} $n$, reward oracle $r$. \emph{Output:} whether $r$ is supermodular, plus a
violating pair if not. \emph{Method:} it suffices to check the local ``diamond'' condition
$r(S\cup\{i\}) + r(S\cup\{j\}) \le r(S) + r(S\cup\{i,j\})$ for all $S$ and all distinct
$i,j\notin S$. \emph{Cost:} $\Theta(2^n n^2)$ versus $\Theta(4^n)$ for the naive all-pairs
test.
\end{algorithmbox}

\section{Applications and discussion}

\textbf{Sample complexity.} Theorem~\ref{thm:binlaw} gives the quality statistic exactly as
$\mathrm{Binomial}(n,\theta)$, with variance $n\theta(1-\theta)$, so estimation precision is
computable a priori.

\textbf{Choosing the regularization strength.} Theorem~\ref{thm:collapse} converts a safety
requirement into an explicit constraint on $a/\beta$; Theorem~\ref{thm:antitone} guarantees
the trade-off curve is strictly monotone, so bisection on $\beta$ is well-posed.

\textbf{Length stability.} Corollary~\ref{cor:scaling} shows all costs scale linearly in the
number of independent coordinates, so a global divergence budget is not length-stable.

\textbf{Reward design.} Proposition~\ref{prop:cone} delimits a practically natural class ---
counting plus non-negative conjunctive bonuses --- for which
Theorems~\ref{thm:fkg} and~\ref{thm:holley} hold. Leaving the supermodular cone forfeits
both guarantees, and that is the precise structural cost of such a design.

\medskip

The results share a common shape: the sigmoid link is the binomial theorem; the mean reward
is Pascal's absorption identity; the impossibility of bimodal degeneration is log-concavity
of the binomial coefficients; the entanglement of desiderata is FKG; the improvement of
every monotone property is Holley; the collapse onto the maximizer is Bernoulli's
inequality; the extensivity of everything is the distributive law.

Two limitations deserve emphasis. The exactly solvable model requires a uniform reference
policy, since a general reference destroys the level-set symmetry behind
Theorem~\ref{thm:transfer} (the FKG/Holley results survive for any log-supermodular
reference). And the closed forms are for additive rewards; for general supermodular rewards
we obtain qualitative structure but no closed form, the partition function of a general
supermodular reward on the Boolean lattice being computationally hard.

\section{Future directions}

\begin{conjecture}[Strict superadditivity of the free energy under synergy]
For a reward on $2^{[m+n]}$ that is supermodular but not modular, the free energy strictly
exceeds the sum of the free energies of its two coordinate restrictions,
$F(r) > F(r|_1)+F(r|_2)$, with equality exactly on the modular cone.
\end{conjecture}
Free-energy additivity (Theorem~\ref{thm:addit}) was proved from the exact factorization of
the partition function for additive rewards, while the four-functions machinery behind
Theorem~\ref{thm:logsuper} gives a one-sided inequality $Z\ge Z_1Z_2$ for supermodular
couplings; superadditivity should therefore follow from the FKG lattice condition rather
than from any analytic estimate. Only the gap term needs to be built.

\begin{conjecture}[Marginal-gain reward-hacking bound]
Let $r$ be monotone and supermodular with minimal marginal gain
$\delta = \min_{S,\,i\notin S}\bigl(r(S\cup\{i\})-r(S)\bigr)>0$. Then
$\pi_\beta(\text{top}) \ge 1 - n e^{-\delta/\beta}$, exactly as in
Theorem~\ref{thm:collapse}, and the exponent $\delta/\beta$ is optimal.
\end{conjecture}
The proof of Theorem~\ref{thm:collapse} used only a per-feature comparison of two responses
differing in one element, so it should localize to marginal gains, with supermodularity
supplying the monotone coupling along maximal chains. The chain-comparison tool behind
Theorem~\ref{thm:holley} is already available, and the counting-reward version is a proved
special case to test against.

\begin{conjecture}[The pretraining mix-in provably de-collapses the policy]
With uniform pretraining distribution $d$ and $\gamma>0$, the maximizer of the augmented
objective over the Bernoulli family is a unique $\theta^*(\gamma)<\sigma(a/\beta)$, strictly
decreasing in $\gamma$; consequently the mass on the reward-maximizing response is strictly
smaller than $\sigma(a/\beta)^n$.
\end{conjecture}
On the Boolean lattice the mix-in term evaluates in closed form,
$\gamma\,\E_d[\log\pi] = \gamma\cdot\frac n2(\log\theta+\log(1-\theta))$, which is strictly
concave and symmetric about $\theta=\tfrac12$, so it acts as an explicit entropic restoring
force pulling the aligned policy back from the corner of the cube.

\section{Conclusion}

On response spaces with combinatorial structure the KL-regularized alignment objective is
exactly solvable. On the Boolean lattice of satisfied features with a uniform reference and
a counting reward, the aligned policy is a product of i.i.d.\ Bernoulli features with a
logistic parameter; the reward statistic is binomial; value, entropy and drift are explicit
and extensive; the quality distribution is unimodal; the mass on the reward-maximizing
response is at least $1-ne^{-a/\beta}$; and both reward and collapse are strictly monotone
in the regularization strength. Replacing additivity by supermodularity, the aligned policy
remains log-supermodular, so desiderata are positively associated and, for monotone rewards,
every monotone property improves relative to the reference.

